sp_widget.client_script:
api.controller = function($rootScope, $scope) {

    var c = this;

    c.activeSection = 'dashboard';

    var menuListener = $rootScope.$on(
        'studentMenuChanged',
        function(event, menuName) {

            c.activeSection = menuName;

        }
    );

    c.openSection = function(section) {

        c.activeSection = section;

        $rootScope.$broadcast(
            'studentMenuChanged',
            section
        );

    };

    c.getStatusClass = function(status) {

        if (!status) {
            return 'status-active';
        }

        var value = status.toLowerCase();

        if (
            value === 'resolved' ||
            value === 'closed' ||
            value === 'completed'
        ) {
            return 'status-resolved';
        }

        if (
            value === 'cancelled' ||
            value === 'canceled'
        ) {
            return 'status-cancelled';
        }

        if (
            value === 'in progress' ||
            value === 'work in progress'
        ) {
            return 'status-progress';
        }

        return 'status-active';
    };

    c.submitComplaint = function() {

        if (typeof g_form === 'undefined') {

            alert(
                'Form is still loading. Please try again.'
            );

            return;
        }

        g_form.submit('sysverb_insert');

    };

    $scope.$on(
        '$destroy',
        function() {

            if (menuListener) {
                menuListener();
            }

        }
    );

};

sp_widget.css:
/* =========================================================
   MAIN CONTENT
   ========================================================= */

.student-content {

    width: 100%;

    min-height: 700px;

    padding: 28px;

    background: #f6f8fb;

    color: #172033;

}


/* =========================================================
   PAGE HEADER
   ========================================================= */

.page-header {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 20px;

    margin-bottom: 25px;

}


.page-heading h1 {

    margin: 0;

    font-size: 26px;

    line-height: 1.3;

    font-weight: 700;

    color: #172033;

}


.page-heading p {

    margin: 7px 0 0;

    font-size: 14px;

    line-height: 1.5;

    color: #6b7280;

}


/* =========================================================
   BUTTONS
   ========================================================= */

.btn {

    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 7px;

    min-height: 40px;

    padding: 9px 16px;

    border-radius: 7px;

    border: 1px solid transparent;

    font-size: 13px;

    font-weight: 600;

    line-height: 1;

    cursor: pointer;

    transition: all 0.18s ease;

}


.btn:hover {

    transform: translateY(-1px);

}


.btn-primary {

    background: #2563eb;

    border-color: #2563eb;

    color: #ffffff;

}


.btn-primary:hover {

    background: #1d4ed8;

    border-color: #1d4ed8;

}


.btn-secondary {

    background: #ffffff;

    border-color: #d7dee8;

    color: #374151;

}


.btn-secondary:hover {

    background: #f8fafc;

    border-color: #cbd5e1;

}


.btn-icon {

    font-size: 17px;

    font-weight: 400;

}


/* =========================================================
   KPI SECTION
   ========================================================= */

.stats-container {

    display: grid;

    grid-template-columns: repeat(4, minmax(0, 1fr));

    gap: 17px;

    margin-bottom: 23px;

}


.stat-card {

    display: flex;

    align-items: center;

    min-height: 128px;

    padding: 20px;

    background: #ffffff;

    border: 1px solid #e5e9ef;

    border-radius: 12px;

    box-shadow: 0 2px 7px rgba(15, 23, 42, 0.035);

    transition: all 0.2s ease;

}


.stat-card:hover {

    transform: translateY(-2px);

    box-shadow: 0 7px 18px rgba(15, 23, 42, 0.07);

}


.stat-icon {

    flex-shrink: 0;

    width: 48px;

    height: 48px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-right: 15px;

    border-radius: 11px;

    font-size: 20px;

    font-weight: 700;

}


.total-icon {

    background: #eef4ff;

    color: #2563eb;

}


.active-icon {

    background: #fff7ed;

    color: #ea580c;

}


.resolved-icon {

    background: #ecfdf5;

    color: #059669;

}


.feedback-icon {

    background: #f5f3ff;

    color: #7c3aed;

}


.stat-info {

    min-width: 0;

}


.stat-title {

    margin-bottom: 4px;

    font-size: 12px;

    font-weight: 600;

    color: #64748b;

}


.stat-number {

    font-size: 29px;

    line-height: 1.1;

    font-weight: 750;

    color: #172033;

}


.stat-description {

    margin-top: 5px;

    font-size: 11px;

    color: #94a3b8;

}


/* =========================================================
   CONTENT CARD
   ========================================================= */

.content-card {

    width: 100%;

    margin-bottom: 22px;

    padding: 21px;

    background: #ffffff;

    border: 1px solid #e5e9ef;

    border-radius: 12px;

    box-shadow: 0 2px 7px rgba(15, 23, 42, 0.035);

}


.card-header {

    display: flex;

    align-items: center;

    justify-content: space-between;

    gap: 15px;

    margin-bottom: 18px;

}


.simple-header {

    margin-bottom: 5px;

}


.card-title {

    margin: 0;

    font-size: 17px;

    line-height: 1.3;

    font-weight: 700;

    color: #172033;

}


.card-subtitle {

    margin: 5px 0 0;

    font-size: 12px;

    line-height: 1.5;

    color: #7b8794;

}


.text-button {

    padding: 5px 0;

    border: none;

    background: transparent;

    color: #2563eb;

    font-size: 12px;

    font-weight: 600;

    cursor: pointer;

}


.text-button:hover {

    color: #1d4ed8;

}


/* =========================================================
   REQUEST TABLE
   ========================================================= */

.table-container {

    width: 100%;

    overflow-x: auto;

    border: 1px solid #edf0f4;

    border-radius: 8px;

}


.request-table {

    width: 100%;

    min-width: 760px;

    border-collapse: collapse;

}


.request-table thead {

    background: #f8fafc;

}


.request-table th {

    padding: 12px 14px;

    text-align: left;

    white-space: nowrap;

    border-bottom: 1px solid #e5e9ef;

    color: #64748b;

    font-size: 11px;

    font-weight: 700;

    text-transform: uppercase;

    letter-spacing: 0.03em;

}


.request-table td {

    padding: 14px;

    border-bottom: 1px solid #f0f2f5;

    color: #475569;

    font-size: 12px;

    vertical-align: middle;

}


.request-table tbody tr:last-child td {

    border-bottom: none;

}


.request-table tbody tr {

    transition: background 0.15s ease;

}


.request-table tbody tr:hover {

    background: #fafcff;

}


.request-number {

    color: #2563eb;

    font-weight: 700;

}


/* =========================================================
   STATUS BADGES
   ========================================================= */

.status-badge {

    display: inline-flex;

    align-items: center;

    padding: 5px 9px;

    border-radius: 20px;

    white-space: nowrap;

    font-size: 10px;

    font-weight: 700;

}


.status-active {

    background: #fff7ed;

    color: #c2410c;

}


.status-progress {

    background: #eff6ff;

    color: #1d4ed8;

}


.status-resolved {

    background: #ecfdf5;

    color: #047857;

}


.status-cancelled {

    background: #fef2f2;

    color: #b91c1c;

}


/* =========================================================
   QUICK ACTIONS
   ========================================================= */

.quick-actions {

    display: grid;

    grid-template-columns: repeat(3, minmax(0, 1fr));

    gap: 13px;

    margin-top: 18px;

}


.quick-action {

    display: flex;

    align-items: center;

    width: 100%;

    min-height: 74px;

    padding: 13px;

    border: 1px solid #e4e9f0;

    border-radius: 9px;

    background: #ffffff;

    text-align: left;

    cursor: pointer;

    transition: all 0.18s ease;

}


.quick-action:hover {

    border-color: #bfdbfe;

    background: #f8fbff;

    transform: translateY(-1px);

    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.07);

}


.quick-action-icon {

    flex-shrink: 0;

    width: 38px;

    height: 38px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-right: 11px;

    border-radius: 9px;

    background: #eff6ff;

    color: #2563eb;

    font-size: 18px;

    font-weight: 700;

}


.quick-action-content {

    min-width: 0;

    flex: 1;

}


.quick-action-content strong {

    display: block;

    margin-bottom: 3px;

    color: #1e293b;

    font-size: 12px;

    font-weight: 700;

}


.quick-action-content span {

    display: block;

    color: #7b8794;

    font-size: 10px;

    line-height: 1.4;

}


.quick-arrow {

    color: #94a3b8;

    font-size: 16px;

    margin-left: 8px;

}


/* =========================================================
   FORM
   ========================================================= */

.form-card {

    padding: 24px;

}


.form-header {

    padding-bottom: 20px;

    margin-bottom: 20px;

    border-bottom: 1px solid #edf0f4;

}


.service-form {

    width: 100%;

}


.form-actions {

    display: flex;

    justify-content: flex-end;

    gap: 10px;

    margin-top: 25px;

    padding-top: 18px;

    border-top: 1px solid #edf0f4;

}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.empty-state {

    display: flex;

    flex-direction: column;

    align-items: center;

    justify-content: center;

    min-height: 240px;

    padding: 35px 20px;

    text-align: center;

}


.empty-icon {

    width: 52px;

    height: 52px;

    display: flex;

    align-items: center;

    justify-content: center;

    margin-bottom: 14px;

    border-radius: 50%;

    background: #eff6ff;

    color: #2563eb;

    font-size: 20px;

}


.feedback-empty-icon {

    background: #f5f3ff;

    color: #7c3aed;

}


.empty-state h3 {

    margin: 0 0 7px;

    color: #334155;

    font-size: 16px;

    font-weight: 700;

}


.empty-state p {

    max-width: 420px;

    margin: 0 0 18px;

    color: #7b8794;

    font-size: 12px;

    line-height: 1.6;

}


/* =========================================================
   HELP
   ========================================================= */

.help-list {

    width: 100%;

}


.help-item {

    display: flex;

    gap: 17px;

    padding: 20px 0;

    border-bottom: 1px solid #edf0f4;

}


.help-item:first-child {

    padding-top: 5px;

}


.help-item:last-child {

    border-bottom: none;

    padding-bottom: 5px;

}


.help-number {

    flex-shrink: 0;

    width: 38px;

    height: 38px;

    display: flex;

    align-items: center;

    justify-content: center;

    border-radius: 8px;

    background: #eff6ff;

    color: #2563eb;

    font-size: 10px;

    font-weight: 700;

}


.help-item h3 {

    margin: 0 0 5px;

    color: #1e293b;

    font-size: 13px;

    font-weight: 700;

}


.help-item p {

    margin: 0;

    color: #7b8794;

    font-size: 12px;

    line-height: 1.6;

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1100px) {

    .stats-container {

        grid-template-columns: repeat(2, minmax(0, 1fr));

    }

    .quick-actions {

        grid-template-columns: 1fr;

    }

}


@media (max-width: 768px) {

    .student-content {

        padding: 18px;

    }

    .page-header {

        align-items: flex-start;

        flex-direction: column;

    }

    .page-header .btn {

        width: 100%;

    }

    .stats-container {

        grid-template-columns: 1fr;

    }

    .card-header {

        align-items: flex-start;

        flex-direction: column;

    }

}


@media (max-width: 480px) {

    .student-content {

        padding: 12px;

    }

    .content-card {

        padding: 16px;

    }

    .page-heading h1 {

        font-size: 22px;

    }

    .stat-card {

        min-height: 110px;

    }

}

sp_widget.link:
api.controller = function($rootScope, $scope) {

    var c = this;

    c.activeSection = 'dashboard';


    /*
     * Sidebar -> Content
     */

    var menuListener = $rootScope.$on(
        'studentMenuChanged',
        function(event, menuName) {

            c.activeSection = menuName;

        }
    );


    /*
     * Dashboard buttons -> Content
     */

    c.openSection = function(section) {

        c.activeSection = section;

        $rootScope.$broadcast(
            'studentMenuChanged',
            section
        );

    };


    /*
     * Cleanup listener
     */

    $scope.$on(
        '$destroy',
        function() {

            if (menuListener) {
                menuListener();
            }

        }
    );
c.submitComplaint = function() {

    if (typeof g_form === 'undefined') {

        alert('Form is still loading. Please try again.');

        return;
    }

    g_form.submit('sysverb_insert');

};
};
